import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForGrowth,validGrowth,advanceGrowth,numericGrowth,drawingValid}from './growth-models.js?v=20261023-physicscomplete01';import{showHormoneGrowth}from './growth-visuals.js?v=20261023-physicscomplete01';export{showHormoneGrowth};
export function mountHormoneGrowth(l,p,root,{save,done,feedback}){let ts=tasksForGrowth(l.widget.slice(8)),w=p.widget;w.growthTask??=ts[0].id;w.growthDrafts??={};w.growthPassed??=[];let i=ts.findIndex(t=>t.id===w.growthTask);if(i<0)i=0;let t=ts[i],v=w.growthDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountHormoneGrowth(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.growthPassed.includes(t.id));
syncProcessMovie(l,1,['setup','length','drawing','applications','biodiversity','logistics','control','gravity'].includes(t.kind)?{process:false}:t.kind==='germination'?{processFilm:'growth-germination'}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('growthCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('growthAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealGrowth">Reveal evidence →</button><p id="growthReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showHormoneGrowth(t.kind,{state:c[0],neutral:t.kind==='glands',title:t.title,label:c[1],concealed:!r&&t.kind!=='glands',progress:r?1:0,step:r?5:0});$('#growthReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validGrowth(c,v.answer);}
else if(t.type==='sequence'){body=field('growthNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceGrowth">Advance pathway →</button><p id="growthReadout" aria-live="polite"></p>';draw=()=>{showHormoneGrowth(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#growthReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}
else if(t.type==='drawing'){let opts=[['shoot','Shoot'],['root','Root'],['seed','Seed']];body='<p>Observed seedling: light from left; gravity down. Match the labels and choose the observed shoot bend.</p>'+field('growthShoot','Label A',opts,v.shoot)+field('growthRoot','Label B',opts,v.root)+field('growthSeed','Label C',opts,v.seed)+field('growthBend','Shoot bend',[['left','Towards left-hand light'],['right','Away to the right'],['straight','No curve']],v.bend);draw=()=>showHormoneGrowth('drawing',{...v,title:t.title});valid=()=>drawingValid(v);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="growthNumber">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="growthNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('growthReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);if(t.kind==='graph')body+='<label class="field-label" for="growthDay">Inspect day</label><input id="growthDay" type="range" min="1" max="28" value="'+(v.day??14)+'">';draw=()=>showHormoneGrowth(t.kind,{title:t.title,day:Number(v.day??14),label:'Original illustrative evidence'});valid=()=>numericGrowth(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="growthEvidence"></p><div class="lab-actions"><button class="secondary" id="recordGrowth">Record reasoning</button><button class="secondary" id="nextGrowth">Next challenge →</button></div><p id="growthProgress"></p>';
const status=()=>{$('#growthEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.growthPassed.includes(t.id)?'Challenge recorded.':'';$('#growthProgress').textContent=ts.filter(t=>w.growthPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='growthDay'){v.day=val;save();draw();return;}if(id==='growthCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(['growthShoot','growthRoot','growthSeed','growthBend'].includes(id)){v[id.slice(6).toLowerCase()]=val;draw();}else if(id==='growthAnswer')v.answer=val;else if(id==='growthNext')v.next=val;else if(id==='growthNumber')v.number=val;else if(id==='growthReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{if(e.target.id==='growthDay'){v.day=e.target.value;draw();}else v.number=e.target.value;save();};}
if($('#revealGrowth'))$('#revealGrowth').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validGrowth(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validGrowth(t.cases[v.case],v.answer));};
if($('#advanceGrowth'))$('#advanceGrowth').onclick=()=>{let n=advanceGrowth(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordGrowth').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.growthPassed.includes(t.id))w.growthPassed.push(t.id);p.widgetDone=ts.every(t=>w.growthPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextGrowth').onclick=()=>{if(!w.growthPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.growthTask=ts[(i+1)%ts.length].id;save();remount();};}
